:root { --announcement-height: 30px; }
.announcement-bar--hidden { display: none !important; }
.announcement-bar--animated { transform: translateY(-100%); opacity: 0; transition: transform 0.5s, opacity 0.5s; }
.announcement-bar--visible { transform: translateY(0px); opacity: 1; }

.search__form { width: 100%; }
.search__form-text { margin-top: 2rem; }
.search .field { position: relative; }
.search__input { padding-inline: 3.4rem 7rem !important; }
.search__button { position: absolute; top: 50%; transform: translateY(-50%); width: 2.2rem; height: 2.2rem; padding: 0px; display: flex; align-items: center; justify-content: center; color: rgb(var(--color-foreground)); transition: opacity var(--duration-default); }
.search__button .icon { width: 1.4rem; height: 1.4rem; }
.search__button .icon.icon-close { width: 2.4rem; height: 2.4rem; }
.search__button--submit, .search__button--reset { right: 0px; }
@media screen and (hover: hover) and (pointer: fine) {
  .search__button:hover { opacity: var(--hover-opacity); }
}
.card-page { position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: 4rem; min-height: 11.5rem; height: auto; padding: 1.6rem; border-radius: var(--border-radius-block); justify-content: space-between; overflow: hidden; color: rgb(var(--color-foreground)); transition: background-color var(--duration-default); background: rgb(var(--color-background-secondary)); }
@media screen and (hover: hover) and (pointer: fine) {
  .card-page:hover .card-page__title { opacity: var(--hover-opacity); }
}
.card-page__title { color: rgb(var(--color-foreground)); transition: color var(--duration-default); font-weight: 400; }
.card-page-wrapper { position: relative; display: block; height: 100%; text-decoration: none; background-color: transparent; }
.card-page__content { text-align: left; }

.menu-drawer { position: fixed; top: 0px; bottom: 1.6rem; left: 0px; width: 100%; height: calc(var(--vh, 1vh) * 100 - (var(--ann-height))); padding: 0px; background-color: rgb(var(--color-background)); border-width: medium; border-style: none; border-color: currentcolor; border-image: none; opacity: 0; visibility: hidden; pointer-events: none; transform: translate(-110%); overflow: hidden; z-index: 100; }
@media only screen and (min-width: 576px) {
  .menu-drawer { max-width: 40rem; }
}
.no-js .menu-drawer { transform: translate(0px); box-shadow: 0 4px 16px rgba(var(--color-shadow),.15); height: calc(100vh - (var(--announcement-height))); }
.no-js .menu-drawer__main { padding-top: 4.8rem; }
.menu-drawer .header__localization .localization-selector + .disclosure__list { padding: 0px; top: auto; left: 0px; right: unset; bottom: 110%; }
.menu-drawer-container { height: 100%; width: 100%; }
.menu-drawer__top { display: flex; align-items: center; justify-content: flex-start; gap: 0.8rem 1.6rem; padding-block: 0.8rem; min-height: var(--header-height); }
.menu-drawer__main { overflow-y: auto; overscroll-behavior: contain; padding-inline: 1.2rem; }
.menu-drawer__main::-webkit-scrollbar { width: 0.3rem; height: 0.3rem; }
.menu-drawer__main::-webkit-scrollbar-thumb { background-color: rgba(var(--color-foreground),.2); border-radius: 2rem; }
.menu-drawer__navigation + .menu-drawer__navigation > .menu-drawer__menu > li:first-child { border-top-width: medium; border-top-style: none; border-top-color: currentcolor; }
.menu-drawer__bottom { min-height: 4.8rem; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 2.4rem; margin-top: auto; padding: 0px 1.2rem; border-top: .1rem solid rgb(var(--color-border)); z-index: 2; }
.menu-drawer__bottom-buttons { margin-inline: auto -1.2rem; height: 100%; display: flex; align-items: center; }
.menu-drawer .header__scheme, .menu-drawer .header__account, .menu-drawer .header__search { display: flex; }
.menu-drawer .header__search .header__search-modal { position: absolute; top: 0px; left: 0px; width: 100%; height: 100%; pointer-events: none; visibility: hidden; overflow: hidden; transform: translate(110%); transition: visibility 0.3s ease-in-out, transform 0.3s ease-in-out; }
.menu-drawer .header__search .header__search-modal.modal--open { pointer-events: all; visibility: visible; transform: translate(0px); }
.menu-drawer .header__search .header__search-modal .modal__content { position: relative; width: 100%; height: 100%; padding: 0px; opacity: 1; transform: none; display: flex; flex-direction: column; overflow: hidden; background-color: rgb(var(--color-background)); }
.menu-drawer .header__search .header__search-modal .search-modal__form { padding: 2.4rem 1.2rem; }
.menu-drawer .header__search .header__search-modal .menu-drawer-search-wrapper { width: 100%; display: flex; flex-direction: column; overflow-y: auto; overscroll-behavior: contain; }
.menu-drawer .header__search .header__search-modal .menu-drawer-search-wrapper::-webkit-scrollbar { width: 0.3rem; height: 0.3rem; }
.menu-drawer .header__search .header__search-modal .menu-drawer-search-wrapper::-webkit-scrollbar-thumb { background-color: rgba(var(--color-foreground),.2); border-radius: 2rem; }
.menu-drawer .header__search-popular { margin: 0px 0px 1.2rem; padding: 0px 1.2rem; overflow: visible; }
.menu-drawer .header__search-collection { width: 100%; margin: auto 0px 0px; }
.menu-drawer .header__region { display: flex; height: 100%; }
.menu-drawer .header__region .modal { position: absolute; top: 0px; height: 100%; }
.menu-drawer .header__region .modal__content { padding: 0px; opacity: 1; }
.menu-drawer .header__region .region-modal__selects { padding: 2.4rem 1.2rem; }
.menu-drawer__inner-container { position: relative; display: flex; flex-direction: column; width: 100%; height: 100%; }
.menu-drawer__inner-container > .modal__heading { padding-top: 1.6rem; }
.menu-drawer__menu > li { border-top: .1rem solid rgb(var(--color-border)); }
.menu-drawer__menu > li:last-child { border-bottom: .1rem solid rgb(var(--color-border)); }
.menu-drawer__menu .menu-drawer__menu-item { color: rgb(var(--color-foreground)); padding-block: 1.2rem; text-decoration: none; width: 100%; display: flex; align-items: center; justify-content: space-between; }
.menu-drawer__menu .menu-drawer__menu-item .icon-chevron { flex-shrink: 0; position: static; width: 1.6rem; height: 1.6rem; transition: opacity var(--duration-default) ease-in-out,transform var(--duration-default) ease-in-out; }
@media screen and (hover: hover) and (pointer: fine) {
  .menu-drawer__menu .menu-drawer__menu-item:hover > .icon-chevron { opacity: var(--hover-opacity); }
  .menu-drawer__menu .menu-drawer__menu-item:not(:has(.menu-drawer__menu-link + .icon-chevron)) { transition: opacity var(--duration-default) ease-in-out; }
  .menu-drawer__menu .menu-drawer__menu-item:not(:has(.menu-drawer__menu-link + .icon-chevron)):hover { opacity: var(--hover-opacity); }
}
.menu-drawer__menu .menu-opening[open] > summary { padding-bottom: 0.4rem; }
.menu-drawer__menu .menu-opening[open] > summary > .icon-chevron { transform: rotate(-180deg); }
@media screen and (hover: hover) and (pointer: fine) {
  .menu-drawer__menu .menu-drawer__menu-link { transition: opacity var(--duration-default) ease-in-out; }
  .menu-drawer__menu .menu-drawer__menu-link:hover { opacity: var(--hover-opacity); }
  .menu-drawer__menu .menu-drawer__menu-link:hover + .icon-chevron { opacity: 1; }
}
.menu-drawer__menu .menu-drawer__menu-link--highlighted, .menu-drawer__menu .menu-drawer__menu-item--highlighted { color: rgb(var(--color-accent)); }
